SERVER_SRC = {"__init__.py": "", "bootstrap.py": "# Embedded by extension/build.py as CC.CLI_SRC: `python3 -c <this>` with one JSON request on stdin.\nimport json, os, sys\n\n\ndef package_dir(req):\n    home = os.path.expanduser(\"~\")\n    for cand in (req.get(\"serverDir\"), os.environ.get(\"CLAUDE_CHAT_HOME\"), os.path.join(home, \".local\", \"share\", \"claude-chat\", \"claude_chat\")):\n        if not cand:\n            continue\n        for d in (cand, os.path.join(cand, \"claude_chat\")):\n            if os.path.basename(d) == \"claude_chat\" and os.path.isfile(os.path.join(d, \"cli.py\")):\n                return os.path.abspath(d)\n    return None\n\n\ndef main():\n    try:\n        req = json.load(sys.stdin)\n    except ValueError as e:\n        print(json.dumps({\"error\": \"bad request: %s\" % e}))\n        sys.exit(1)\n    d = package_dir(req)\n    if d is None:\n        print(json.dumps({\"error\": \"claude-chat server not installed: run server/setup.py --server (or set CLAUDE_CHAT_HOME)\"}))\n        sys.exit(1)\n    sys.path.insert(0, os.path.dirname(d))\n    from claude_chat import cli\n    cli.main(req)\n\n\nmain()\n", "cli.py": "#!/usr/bin/env python3\nimport fcntl, json, os, signal, subprocess, sys, time, uuid\n\nHERE = os.path.dirname(os.path.abspath(__file__))\nsys.path.insert(0, HERE)\nimport config, procs\nimport state as S\nimport tui\n\nDAEMON = os.path.join(HERE, \"daemon.py\")\nPERMISSION_MODES = {\"acceptEdits\", \"auto\", \"bypassPermissions\", \"manual\", \"default\", \"dontAsk\", \"plan\"}\n\n\ndef daemon_marker(d):\n    return os.path.basename(DAEMON) + \" \" + d\n\n\ndef daemon_alive(d, st):\n    return procs.alive(st.get(\"pid\"), daemon_marker(d), st.get(\"pidStarted\"))\n\n\ndef cli_alive(st):\n    return procs.alive(st.get(\"cliPid\"), st.get(\"cliMarker\"), st.get(\"cliPidStarted\"))\n\n\ndef locked(d):\n    lock = open(os.path.join(d, \"lock\"), \"w\")\n    fcntl.flock(lock, fcntl.LOCK_EX)\n    return lock\n\n\n# A daemon gone without its `stopped` event is repaired here, under the session lock so two ops never both write it.\ndef load_state(d, have_lock=False):\n    st = S.read_state(d)\n    if st is None:\n        return None\n    if st.get(\"status\") != \"stopped\" and not daemon_alive(d, st):\n        lock = None if have_lock else locked(d)\n        try:\n            st = S.read_state(d) or st\n            if st.get(\"status\") != \"stopped\" and not daemon_alive(d, st):\n                if cli_alive(st):\n                    os.kill(int(st[\"cliPid\"]), signal.SIGTERM)\n                seq = S.last_seq(d) + 1\n                S.append_event(d, seq, {\"type\": \"daemon\", \"subtype\": \"stopped\", \"reason\": \"dead\", \"exitCode\": None})\n                st.update({\"status\": \"stopped\", \"reason\": \"dead\", \"pid\": None, \"cliPid\": None, \"pending\": [], \"promptQueue\": [],\n                           \"turn\": {\"startedAt\": None, \"promptId\": None}, \"stoppedAt\": S.now_ms(), \"lastSeq\": seq})\n                S.write_state(d, st)\n        finally:\n            if lock is not None:\n                lock.close()\n    st[\"lastSeq\"] = max(int(st.get(\"lastSeq\") or 0), S.last_seq(d))\n    return st\n\n\ndef session(req):\n    d = config.session_dir(req.get(\"sessionId\") or \"\")\n    if not os.path.isdir(d):\n        raise SystemExit(\"unknown session %s\" % req.get(\"sessionId\"))\n    return d\n\n\ndef running(req):\n    d = session(req)\n    st = load_state(d)\n    if not st or st.get(\"status\") == \"stopped\":\n        raise SystemExit(\"session not running\")\n    if st.get(\"status\") == \"stopping\":\n        raise SystemExit(\"session is stopping\")\n    return d, st\n\n\ndef op_start(req):\n    cwd = req.get(\"cwd\") or \"\"\n    if not os.path.isdir(cwd):\n        raise SystemExit(\"cwd not found: %s\" % cwd)\n    sid = req.get(\"sessionId\") or str(uuid.uuid4())\n    d = config.session_dir(sid)\n    os.makedirs(d, exist_ok=True)\n    with locked(d):\n        st = load_state(d, have_lock=True)\n        if st and st.get(\"status\") != \"stopped\":\n            return {\"sessionId\": sid, \"pid\": st.get(\"pid\"), \"started\": False}\n        if not config.claude_bin():\n            raise SystemExit(\"claude binary not found (PATH, ~/.local/bin/claude or config claudeBin)\")\n        prev = st or {}\n        cli_sid = req.get(\"cliSessionId\") or prev.get(\"cliSessionId\") or sid\n        resume = req.get(\"resume\")\n        if resume is None:\n            resume = bool(prev.get(\"lastSeq\"))\n        # --resume of a conversation the CLI never wrote loops on \"No conversation found\": start fresh under the same id\n        if resume and not os.path.isfile(tui.transcript_path(os.path.abspath(cwd), cli_sid)):\n            resume = False\n        S.rotate_events(d)\n        args = {\"sessionId\": sid, \"cliSessionId\": cli_sid, \"cwd\": os.path.abspath(cwd), \"resume\": bool(resume),\n                \"fork\": bool(req.get(\"forkSession\")), \"partial\": req.get(\"partial\", True) is not False,\n                \"model\": req.get(\"model\") or (prev.get(\"model\") if resume else None),\n                \"effort\": req.get(\"effort\") or (prev.get(\"effort\") if resume else None),\n                \"permissionMode\": req.get(\"permissionMode\") or (prev.get(\"permissionMode\") if resume and prev.get(\"permissionMode\") in PERMISSION_MODES else None)}\n        with open(os.path.join(d, \"daemon.log\"), \"ab\") as log:\n            p = subprocess.Popen([sys.executable, DAEMON, d, json.dumps(args)], cwd=args[\"cwd\"], stdin=subprocess.DEVNULL, stdout=log, stderr=log,\n                                 start_new_session=True, close_fds=True)\n        deadline = time.time() + 10\n        while time.time() < deadline:\n            st = S.read_state(d)\n            if st and st.get(\"pid\") == p.pid:\n                return {\"sessionId\": sid, \"pid\": p.pid, \"started\": True, \"resumed\": bool(resume)}\n            if p.poll() is not None:\n                break\n            time.sleep(0.05)\n        raise SystemExit(\"daemon did not start: \" + tail(os.path.join(d, \"daemon.log\")))\n\n\ndef tail(path, n=1500):\n    try:\n        with open(path, \"rb\") as fh:\n            fh.seek(0, 2)\n            fh.seek(max(0, fh.tell() - n))\n            return fh.read().decode(\"utf-8\", \"replace\").strip()\n    except OSError:\n        return \"\"\n\n\ndef op_stop(req):\n    d = session(req)\n    st = load_state(d)\n    if not st or st.get(\"status\") == \"stopped\":\n        prune(d, st)\n        return {\"ok\": True, \"id\": None}\n    rid = S.append_inbox(d, {\"type\": \"stop\", \"force\": bool(req.get(\"force\"))})\n    if req.get(\"force\") and daemon_alive(d, st):\n        os.kill(int(st[\"pid\"]), signal.SIGTERM)\n    return {\"ok\": True, \"id\": rid}\n\n\n# Stopped sessions only: the consumed part of the inbox (base64 images) goes; the daemon does the same when it exits.\ndef prune(d, st):\n    if not st or st.get(\"status\") != \"stopped\":\n        return {\"ok\": False, \"inboxBytes\": None}\n    with locked(d):\n        st = S.read_state(d) or st\n        if st.get(\"status\") != \"stopped\":\n            return {\"ok\": False, \"inboxBytes\": None}\n        kept = S.prune_inbox(d, int(st.get(\"inboxOffset\") or 0))\n        if st.get(\"inboxOffset\"):\n            st[\"inboxOffset\"] = 0\n            S.write_state(d, st)\n    return {\"ok\": True, \"inboxBytes\": kept}\n\n\ndef op_prune(req):\n    d = session(req)\n    return prune(d, load_state(d))\n\n\ndef op_send(req):\n    d, _ = running(req)\n    cmd = {\"type\": \"prompt\", \"text\": req.get(\"text\") or \"\", \"clientId\": req.get(\"clientId\")}\n    if req.get(\"images\"):\n        cmd[\"images\"] = req[\"images\"]\n    return {\"id\": S.append_inbox(d, cmd)}\n\n\ndef op_send_chunk(req):\n    d, _ = running(req)\n    return {\"id\": S.append_inbox(d, {\"type\": \"prompt_chunk\", \"chunkId\": req.get(\"chunkId\"), \"index\": int(req.get(\"index\") or 0),\n                                     \"total\": int(req.get(\"total\") or 1), \"data\": req.get(\"data\") or \"\"})}\n\n\ndef op_respond(req):\n    d, _ = running(req)\n    cmd = {\"type\": \"respond\", \"requestId\": req.get(\"requestId\"), \"behavior\": req.get(\"behavior\") or \"deny\"}\n    for k in (\"updatedInput\", \"updatedPermissions\", \"message\"):\n        if req.get(k) is not None:\n            cmd[k] = req[k]\n    return {\"id\": S.append_inbox(d, cmd)}\n\n\ndef op_interrupt(req):\n    d, _ = running(req)\n    return {\"id\": S.append_inbox(d, {\"type\": \"interrupt\"})}\n\n\ndef op_control(req):\n    d, _ = running(req)\n    cmd = {k: v for k, v in req.items() if k not in (\"op\", \"sessionId\")}\n    cmd[\"type\"] = \"control\"\n    if not cmd.get(\"subtype\"):\n        raise SystemExit(\"control needs subtype\")\n    return {\"id\": S.append_inbox(d, cmd)}\n\n\ndef state_or_stub(d, sid):\n    return load_state(d) or {\"sessionId\": sid, \"status\": \"stopped\", \"version\": 0, \"lastSeq\": 0, \"pending\": []}\n\n\n# Written by the optional claude-pane-title hook (Haiku): a topic that follows the conversation.\ndef topic_path(st):\n    sid = st.get(\"cliSessionId\") or st.get(\"sessionId\") or \"\"\n    return os.path.join(os.path.expanduser(\"~\"), \".cache\", \"claude-pane-title\", sid + \".json\")\n\n\ndef topic_mtime(st):\n    try:\n        return os.stat(topic_path(st)).st_mtime\n    except OSError:\n        return 0\n\n\ndef with_topic(res, st):\n    at = topic_mtime(st)\n    if at > 0:\n        res[\"topic\"] = (S.read_json(topic_path(st)) or {}).get(\"topic\")\n        res[\"topicAt\"] = at\n    return res\n\n\ndef op_events(req):\n    d = session(req)\n    tail = S.last_seq(d)\n    events, more = S.read_events(d, int(req.get(\"after\") or 0), int(req.get(\"limit\") or 500))\n    st = state_or_stub(d, req.get(\"sessionId\"))\n    # the cursor must not run ahead of what was returned: events may land between the read and the state load\n    return with_topic({\"events\": events, \"lastSeq\": events[-1][\"seq\"] if events else tail, \"state\": st, \"more\": more}, st)\n\n\ndef op_wait(req):\n    d = session(req)\n    after = int(req.get(\"after\") or 0)\n    version = int(req.get(\"stateVersion\") or 0)\n    deadline = time.time() + min(int(req.get(\"timeoutMs\") or 25000), 25000) / 1000.0\n    topic_at = float(req.get(\"topicAt\") or 0)\n    path = os.path.join(d, \"state.json\")\n    while True:\n        tail = S.last_seq(d)\n        st = S.read_json(path) or {\"sessionId\": req.get(\"sessionId\")}\n        if tail > after or int(st.get(\"version\") or 0) > version or topic_mtime(st) > topic_at:\n            return op_events(req)\n        if time.time() >= deadline:\n            st = state_or_stub(d, req.get(\"sessionId\"))\n            return with_topic({\"events\": [], \"lastSeq\": tail, \"state\": st, \"more\": False}, st)\n        time.sleep(0.08)\n\n\ndef op_state(req):\n    d = config.session_dir(req.get(\"sessionId\") or \"\")\n    if not os.path.isdir(d):\n        raise SystemExit(\"unknown session %s\" % req.get(\"sessionId\"))\n    return state_or_stub(d, req.get(\"sessionId\"))\n\n\ndef op_list(req):\n    out = []\n    try:\n        names = os.listdir(config.SESSIONS)\n    except OSError:\n        names = []\n    for sid in names:\n        d = os.path.join(config.SESSIONS, sid)\n        st = load_state(d)\n        if not st or (req.get(\"cwd\") and st.get(\"cwd\") != req[\"cwd\"]):\n            continue\n        out.append({\"sessionId\": sid, \"cwd\": st.get(\"cwd\"), \"status\": st.get(\"status\"), \"pid\": st.get(\"pid\"), \"lastSeq\": st.get(\"lastSeq\"),\n                    \"updatedAt\": st.get(\"updatedAt\"), \"model\": st.get(\"model\"), \"reason\": st.get(\"reason\"), \"cliSessionId\": st.get(\"cliSessionId\")})\n    out.sort(key=lambda s: -(s[\"updatedAt\"] or 0))\n    return {\"sessions\": out}\n\n\nOPS = {\"start\": op_start, \"stop\": op_stop, \"send\": op_send, \"sendChunk\": op_send_chunk, \"respond\": op_respond, \"interrupt\": op_interrupt,\n       \"control\": op_control, \"events\": op_events, \"wait\": op_wait, \"state\": op_state, \"list\": op_list, \"prune\": op_prune}\nOPS.update(tui.OPS)\n\n\ndef main(req=None):\n    try:\n        if req is None:\n            req = json.load(sys.stdin)\n        op = OPS.get(req.get(\"op\"))\n        if not op:\n            raise SystemExit(\"unknown op %r\" % req.get(\"op\"))\n        print(json.dumps(op(req), ensure_ascii=False))\n    except SystemExit as e:\n        print(json.dumps({\"error\": str(e)}))\n        sys.exit(1)\n\n\nif __name__ == \"__main__\":\n    main()\n", "config.py": "import json, os, re, shutil\n\nHOME = os.path.expanduser(\"~\")\nSTATE = os.path.join(os.environ.get(\"XDG_CACHE_HOME\") or os.path.join(HOME, \".cache\"), \"claude-chat\")\nSESSIONS = os.path.join(STATE, \"sessions\")\nCONFIG = os.path.join(os.environ.get(\"XDG_CONFIG_HOME\") or os.path.join(HOME, \".config\"), \"claude-chat\", \"config.json\")\nDEFAULTS = {\"claudeBin\": None, \"idleStopMs\": 6 * 3600 * 1000, \"stopWaitMs\": 60000, \"stopKillMs\": 10000, \"extraArgs\": []}\nSID_RE = re.compile(r\"^[A-Za-z0-9_-]{1,80}$\")\n\n\ndef load():\n    cfg = dict(DEFAULTS)\n    try:\n        with open(CONFIG) as fh:\n            cfg.update(json.load(fh))\n    except (OSError, ValueError):\n        pass\n    return cfg\n\n\ndef claude_bin(cfg=None):\n    cfg = cfg or load()\n    for cand in [cfg.get(\"claudeBin\"), shutil.which(\"claude\"), os.path.join(HOME, \".local\", \"bin\", \"claude\")]:\n        if cand and os.path.isfile(cand) and os.access(cand, os.X_OK):\n            return cand\n    return None\n\n\ndef session_dir(sid):\n    if not SID_RE.match(sid or \"\"):\n        raise SystemExit(\"bad sessionId\")\n    return os.path.join(SESSIONS, sid)\n", "daemon.py": "import json, os, queue, signal, subprocess, sys, threading, time, uuid\n\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\nimport config, procs, protocol\nimport state as S\n\nSTOP_WAIT_S = 60\nSTOP_KILL_S = 10\nPOLL_S = 0.1\nSTATE_THROTTLE_S = 0.25\n\n\ndef log(*parts):\n    sys.stderr.write(time.strftime(\"%H:%M:%S \") + \" \".join(str(p) for p in parts) + \"\\n\")\n    sys.stderr.flush()\n\n\ndef log_tail(d, n=2000):\n    try:\n        with open(os.path.join(d, \"daemon.log\"), \"rb\") as fh:\n            fh.seek(0, 2)\n            fh.seek(max(0, fh.tell() - n))\n            return fh.read().decode(\"utf-8\", \"replace\").strip()\n    except OSError:\n        return \"\"\n\n\nclass Daemon:\n    def __init__(self, d, args):\n        self.d = d\n        self.args = args\n        self.cfg = config.load()\n        self.state = S.read_state(d) or S.new_state(args[\"sessionId\"], args[\"cwd\"])\n        self.seq = S.last_seq(d)\n        self.lines = queue.Queue()\n        self.proc = None\n        self.eof = False\n        self.init_done = False\n        self.control = {}\n        self.chunks = {}\n        self.stopping = None\n        self.stop_deadline = None\n        self.kill_deadline = None\n        self.stop_wait = float(self.cfg.get(\"stopWaitMs\") or STOP_WAIT_S * 1000) / 1000.0\n        self.stop_kill = float(self.cfg.get(\"stopKillMs\") or STOP_KILL_S * 1000) / 1000.0\n        self.last_activity = time.time()\n        self.dirty = 0\n        self.last_write = 0\n\n    # --- state / events ---\n    def mark(self, level=2):\n        self.dirty = max(self.dirty, level)\n\n    def apply(self, up):\n        if up:\n            self.state.update(up)\n            self.mark(2)\n\n    def flush(self, force=False):\n        if not self.dirty:\n            return\n        if self.dirty == 1 and not force and time.time() - self.last_write < STATE_THROTTLE_S:\n            return\n        if self.state[\"status\"] not in (\"starting\", \"stopping\", \"stopped\"):\n            self.state[\"status\"] = protocol.status_of(self.state)\n        S.write_state(self.d, self.state)\n        self.dirty = 0\n        self.last_write = time.time()\n\n    def emit(self, ev, level=2):\n        self.seq += 1\n        S.append_event(self.d, self.seq, ev)\n        self.state[\"lastSeq\"] = self.seq\n        self.mark(level)\n\n    def daemon_event(self, subtype, **kw):\n        ev = {\"type\": \"daemon\", \"subtype\": subtype}\n        ev.update(kw)\n        self.emit(ev)\n\n    # --- CLI process ---\n    def send(self, obj):\n        if not self.proc or self.proc.stdin.closed:\n            raise BrokenPipeError(\"cli stdin closed\")\n        self.proc.stdin.write((json.dumps(obj, ensure_ascii=False) + \"\\n\").encode())\n        self.proc.stdin.flush()\n\n    def reader(self):\n        try:\n            for line in self.proc.stdout:\n                self.lines.put(line)\n        finally:\n            self.lines.put(None)\n\n    def spawn(self):\n        claude = config.claude_bin(self.cfg)\n        if not claude:\n            self.fail(\"claude binary not found (PATH, ~/.local/bin/claude or config claudeBin)\")\n            return False\n        a = self.args\n        argv = protocol.build_argv(claude, a.get(\"cliSessionId\") or a[\"sessionId\"], resume=bool(a.get(\"resume\")), fork=bool(a.get(\"fork\")),\n                                   model=a.get(\"model\"), effort=a.get(\"effort\"), permission_mode=a.get(\"permissionMode\"),\n                                   partial=a.get(\"partial\", True), extra=self.cfg.get(\"extraArgs\"))\n        log(\"spawn\", json.dumps(argv))\n        try:\n            # the daemon ignores SIGHUP; the CLI must not inherit that\n            self.proc = subprocess.Popen(argv, cwd=a[\"cwd\"], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=sys.stderr.fileno(),\n                                         env=protocol.cli_env(os.environ), preexec_fn=lambda: signal.signal(signal.SIGHUP, signal.SIG_DFL))\n        except OSError as e:\n            self.fail(\"cannot start claude: %s\" % e)\n            return False\n        self.state[\"cliPid\"] = self.proc.pid\n        self.state[\"cliPidStarted\"] = procs.start_time(self.proc.pid)\n        self.state[\"cliMarker\"] = a.get(\"cliSessionId\") or a[\"sessionId\"]\n        threading.Thread(target=self.reader, daemon=True).start()\n        self.daemon_event(\"started\", pid=os.getpid(), argv=argv, cliVersion=self.state.get(\"cliVersion\"), resumed=bool(a.get(\"resume\")))\n        try:\n            self.send(protocol.initialize_request())\n        except OSError as e:\n            log(\"initialize write failed:\", e)\n        return True\n\n    def fail(self, error):\n        log(\"error:\", error)\n        self.daemon_event(\"error\", error=error)\n        self.finish(\"error\", None, error)\n\n    def finish(self, reason, exit_code, error=None):\n        self.stopping = self.stopping or reason\n        self.poll_inbox()\n        ev = {\"reason\": reason, \"exitCode\": exit_code}\n        if error:\n            ev[\"error\"] = error\n        self.daemon_event(\"stopped\", **ev)\n        S.prune_inbox(self.d, self.state.get(\"inboxOffset\") or 0)\n        self.state.update({\"status\": \"stopped\", \"stoppedAt\": S.now_ms(), \"reason\": reason, \"pid\": None, \"cliPid\": None, \"pending\": [],\n                           \"promptQueue\": [], \"promptUuids\": {}, \"startedUuids\": [], \"followUp\": False, \"turn\": {\"startedAt\": None, \"promptId\": None}, \"activity\": None, \"inboxOffset\": 0,\n                           \"tasks\": protocol.stopped_tasks(self.state)})\n        self.flush(force=True)\n        try:\n            os.remove(os.path.join(self.d, \"daemon.pid\"))\n        except OSError:\n            pass\n        log(\"stopped\", reason, exit_code)\n        sys.exit(0)\n\n    def begin_stop(self, reason, force=False):\n        if self.stopping:\n            if force and self.proc is not None and self.proc.poll() is None:\n                self.proc.terminate()\n            return\n        log(\"stopping:\", reason, \"force\" if force else \"\")\n        self.stopping = reason\n        self.stop_deadline = time.time() + (5 if force else self.stop_wait)\n        self.state[\"status\"] = \"stopping\"\n        self.mark(2)\n        if self.proc is None:\n            return\n        self.close_stdin()\n        if force and self.proc.poll() is None:\n            self.proc.terminate()\n\n    def close_stdin(self):\n        try:\n            self.proc.stdin.close()\n        except OSError:\n            pass\n\n    # --- CLI stdout ---\n    def handle_line(self, line):\n        ev = protocol.parse_line(line)\n        if ev is None:\n            return\n        t = ev.get(\"type\")\n        self.emit(ev, 1 if t == \"stream_event\" else 2)\n        up = protocol.apply_event(self.state, ev, S.now_ms())\n        if t == \"control_response\":\n            r = ev.get(\"response\") or {}\n            rid = r.get(\"request_id\")\n            if rid == protocol.INIT_REQUEST_ID:\n                self.init_done = True\n                if self.state[\"status\"] == \"starting\":\n                    self.state[\"status\"] = \"idle\"\n            req = self.control.pop(rid, None)\n            if req is not None:\n                target = protocol.rewound_target(req, r)\n                if target:\n                    self.daemon_event(\"rewound\", id=rid, target=target)\n                self.daemon_event(\"control_result\", id=rid, response=r)\n                up.update(protocol.apply_control_result(self.state, req, r))\n        if t in (\"result\", \"control_request\"):\n            self.last_activity = time.time()\n        self.apply(up)\n\n    # --- inbox ---\n    def poll_inbox(self):\n        lines, off = S.read_new_lines(os.path.join(self.d, \"inbox.jsonl\"), self.state.get(\"inboxOffset\") or 0)\n        if not lines:\n            return\n        self.state[\"inboxOffset\"] = off\n        self.mark(2)\n        for raw in lines:\n            try:\n                entry = json.loads(raw)\n            except ValueError:\n                log(\"inbox: bad line\", raw[:200])\n                continue\n            self.handle_cmd(entry)\n\n    def handle_cmd(self, entry):\n        cid = entry.get(\"id\")\n        cmd = entry.get(\"cmd\") or {}\n        t = cmd.get(\"type\")\n        self.last_activity = time.time()\n        if self.stopping and t == \"stop\":\n            self.daemon_event(\"accepted\", id=cid, cmd=\"stop\")\n            self.begin_stop(\"stop\", force=bool(cmd.get(\"force\")))\n            return\n        if self.stopping:\n            self.daemon_event(\"rejected\", id=cid, error=\"daemon is stopping\")\n            return\n        try:\n            if t == \"prompt\":\n                self.prompt(cid, cmd)\n            elif t == \"prompt_chunk\":\n                self.chunk(cid, cmd)\n            elif t == \"respond\":\n                self.respond(cid, cmd)\n            elif t == \"interrupt\":\n                self.send(protocol.control_request(cid, \"interrupt\"))\n                self.control[cid] = {\"subtype\": \"interrupt\"}\n                self.daemon_event(\"accepted\", id=cid, cmd=\"interrupt\")\n            elif t == \"control\":\n                self.control_cmd(cid, cmd)\n            elif t == \"stop\":\n                self.daemon_event(\"accepted\", id=cid, cmd=\"stop\")\n                self.begin_stop(\"stop\", force=bool(cmd.get(\"force\")))\n            else:\n                self.daemon_event(\"rejected\", id=cid, error=\"unknown command type %r\" % t)\n        except (BrokenPipeError, OSError, ValueError) as e:\n            self.daemon_event(\"rejected\", id=cid, error=\"cli stdin: %s\" % e)\n\n    def prompt(self, cid, cmd):\n        text = cmd.get(\"text\") or \"\"\n        m = protocol.MODEL_CMD_RE.match(text)\n        if m:\n            # a set_model control outlives a later `/model x` local command, so mirror the slash command as a control\n            req = protocol.control_request(cid + \":model\", \"set_model\", {\"model\": m.group(1)})\n            self.control[req[\"request_id\"]] = req[\"request\"]\n            self.send(req)\n        uid = str(uuid.uuid4())\n        self.send(protocol.user_message(text, cmd.get(\"images\"), uid))\n        self.apply(protocol.apply_prompt(self.state, cid, text, S.now_ms(), uid))\n        self.daemon_event(\"accepted\", id=cid, cmd=\"prompt\", text=text, images=len(cmd.get(\"images\") or []), clientId=cmd.get(\"clientId\"), uuid=uid)\n\n    def chunk(self, cid, cmd):\n        key = cmd.get(\"chunkId\")\n        total = int(cmd.get(\"total\") or 0)\n        c = self.chunks.setdefault(key, {})\n        c[int(cmd.get(\"index\") or 0)] = cmd.get(\"data\") or \"\"\n        if len(c) < total:\n            self.daemon_event(\"accepted\", id=cid, cmd=\"prompt_chunk\")\n            return\n        del self.chunks[key]\n        try:\n            full = json.loads(\"\".join(c[i] for i in range(total)))\n        except (ValueError, KeyError) as e:\n            self.daemon_event(\"rejected\", id=cid, error=\"bad prompt chunks: %s\" % e)\n            return\n        self.prompt(cid, full)\n\n    def respond(self, cid, cmd):\n        rid = cmd.get(\"requestId\")\n        pending = self.state.get(\"pending\") or []\n        if not any(p[\"requestId\"] == rid for p in pending):\n            self.daemon_event(\"rejected\", id=cid, error=\"unknown requestId %r\" % rid)\n            return\n        self.send(protocol.control_response(rid, protocol.respond_payload(cmd)))\n        self.apply({\"pending\": [p for p in pending if p[\"requestId\"] != rid]})\n        self.daemon_event(\"accepted\", id=cid, cmd=\"respond\")\n\n    def control_cmd(self, cid, cmd):\n        sub = cmd.get(\"subtype\")\n        payload = {k: v for k, v in cmd.items() if k not in (\"type\", \"subtype\")}\n        self.daemon_event(\"accepted\", id=cid, cmd=\"control\")\n        if sub == \"supported_commands\":\n            self.daemon_event(\"control_result\", id=cid, response={\"subtype\": \"success\", \"request_id\": cid, \"response\": {\"commands\": self.state.get(\"commands\") or []}})\n            return\n        sub = protocol.CONTROL_ALIASES.get(sub, sub)\n        req = protocol.control_request(cid, sub, payload)\n        self.control[cid] = req[\"request\"]\n        self.send(req)\n\n    # --- main loop ---\n    def run(self):\n        os.makedirs(self.d, exist_ok=True)\n        with open(os.path.join(self.d, \"daemon.pid\"), \"w\") as fh:\n            fh.write(str(os.getpid()))\n        try:\n            self.state[\"inboxOffset\"] = os.path.getsize(os.path.join(self.d, \"inbox.jsonl\"))\n        except OSError:\n            self.state[\"inboxOffset\"] = 0\n        self.state.update({\"pid\": os.getpid(), \"pidStarted\": procs.start_time(os.getpid()), \"cliPid\": None, \"cliPidStarted\": None, \"cliMarker\": None,\n                           \"status\": \"starting\", \"startedAt\": S.now_ms(), \"stoppedAt\": None, \"reason\": None,\n                           \"pending\": [], \"promptQueue\": [], \"promptUuids\": {}, \"startedUuids\": [], \"followUp\": False, \"turn\": {\"startedAt\": None, \"promptId\": None}, \"activity\": None, \"cwd\": self.args[\"cwd\"],\n                           \"tasks\": protocol.stopped_tasks(self.state)})\n        for k in (\"model\", \"effort\", \"permissionMode\"):\n            if self.args.get(k):\n                self.state[k] = self.args[k]\n        self.mark(2)\n        self.flush(force=True)\n        signal.signal(signal.SIGTERM, lambda *a: self.begin_stop(\"stop\", force=True))\n        signal.signal(signal.SIGHUP, signal.SIG_IGN)\n        if self.stopping:\n            self.finish(self.stopping, None)\n        if not self.spawn():\n            return\n        if self.stopping:\n            # SIGTERM landed during the spawn\n            self.close_stdin()\n            self.proc.terminate()\n        idle_s = float(self.cfg.get(\"idleStopMs\") or 0) / 1000.0\n        while True:\n            try:\n                line = self.lines.get(timeout=POLL_S)\n                while True:\n                    if line is None:\n                        self.eof = True\n                    else:\n                        self.handle_line(line)\n                    line = self.lines.get_nowait()\n            except queue.Empty:\n                pass\n            self.poll_inbox()\n            code = self.proc.poll()\n            if code is not None and (self.eof or self.stopping):\n                self.flush(force=True)\n                if self.stopping:\n                    self.finish(self.stopping, code)\n                elif code != 0 or not self.init_done:\n                    self.finish(\"error\", code, \"claude exited with code %s: %s\" % (code, log_tail(self.d)))\n                else:\n                    self.finish(\"exit\", code)\n            if self.stopping and self.kill_deadline is not None and time.time() > self.kill_deadline:\n                log(\"stop timeout, SIGKILL\")\n                self.proc.kill()\n                try:\n                    self.proc.wait(timeout=5)\n                except subprocess.TimeoutExpired:\n                    pass\n                self.finish(self.stopping, -9)\n            if self.stopping and self.kill_deadline is None and time.time() > self.stop_deadline:\n                log(\"stop timeout, SIGTERM\")\n                self.proc.terminate()\n                self.kill_deadline = time.time() + self.stop_kill\n            if not self.stopping and idle_s > 0 and not self.state.get(\"pending\") and not self.state.get(\"promptQueue\") \\\n                    and not self.state.get(\"followUp\") \\\n                    and time.time() - self.last_activity > idle_s:\n                self.begin_stop(\"idle\")\n            self.flush()\n\n\ndef main():\n    d = sys.argv[1]\n    args = json.loads(sys.argv[2])\n    Daemon(d, args).run()\n\n\nif __name__ == \"__main__\":\n    main()\n", "procs.py": "\"\"\"Process identity checks that work without /proc (macOS): cmdline + start time, so a reused pid is never mistaken\nfor our daemon or CLI.\"\"\"\nimport os, subprocess\n\n\ndef ps(field, pid):\n    try:\n        out = subprocess.run([\"ps\", \"-o\", field + \"=\", \"-p\", str(int(pid))], capture_output=True, text=True, timeout=5).stdout\n    except (OSError, subprocess.SubprocessError, ValueError):\n        return None\n    return out.strip() or None\n\n\ndef cmdline(pid):\n    try:\n        with open(\"/proc/%d/cmdline\" % int(pid), \"rb\") as fh:\n            data = fh.read()\n        if data:\n            return data.replace(b\"\\0\", b\" \").decode(\"utf-8\", \"replace\").strip()\n    except (OSError, ValueError):\n        pass\n    return ps(\"command\", pid)\n\n\ndef start_time(pid):\n    try:\n        with open(\"/proc/%d/stat\" % int(pid)) as fh:\n            return \"proc:\" + fh.read().rsplit(\")\", 1)[1].split()[19]\n    except (OSError, ValueError, IndexError):\n        pass\n    t = ps(\"lstart\", pid)\n    return \"ps:\" + t if t else None\n\n\ndef exists(pid):\n    try:\n        os.kill(int(pid), 0)\n        return True\n    except PermissionError:\n        return True\n    except (OSError, ValueError, TypeError):\n        return False\n\n\n# True only for a live process whose argv contains `marker` and (when recorded) whose start time matches.\ndef alive(pid, marker, started=None):\n    if not pid or not marker or not exists(pid):\n        return False\n    cmd = cmdline(pid)\n    if cmd is None or marker not in cmd:\n        return False\n    if started and start_time(pid) != started:\n        return False\n    return True\n", "protocol.py": "import json, re\n\nINIT_REQUEST_ID = \"init\"\nEFFORT_RE = re.compile(r\"Set effort level to (\\w+)\")\nMODEL_CMD_RE = re.compile(r\"^/model\\s+(\\S+)\")\nEFFORT_CMD_RE = re.compile(r\"^/effort\\s+(\\S+)\")\nRENAME_CMD_RE = re.compile(r\"^/rename\\s+(.+?)\\s*$\")\n# inbox control subtypes that the CLI spells differently\nCONTROL_ALIASES = {\"supported_models\": \"list_models\"}\n\n\ndef build_argv(claude_bin, session_id, resume=False, fork=False, model=None, effort=None, permission_mode=None, partial=True, extra=None):\n    argv = [claude_bin, \"-p\", \"--input-format\", \"stream-json\", \"--output-format\", \"stream-json\", \"--verbose\",\n            \"--permission-prompt-tool\", \"stdio\"]\n    if partial:\n        argv.append(\"--include-partial-messages\")\n    if permission_mode:\n        argv += [\"--permission-mode\", permission_mode]\n    if model:\n        argv += [\"--model\", model]\n    if effort:\n        argv += [\"--effort\", effort]\n    if resume:\n        argv += [\"--resume\", session_id]\n        if fork:\n            argv.append(\"--fork-session\")\n    else:\n        argv += [\"--session-id\", session_id]\n    return argv + list(extra or [])\n\n\ndef control_request(request_id, subtype, payload=None):\n    req = {\"subtype\": subtype}\n    req.update(payload or {})\n    return {\"type\": \"control_request\", \"request_id\": request_id, \"request\": req}\n\n\ndef initialize_request():\n    return control_request(INIT_REQUEST_ID, \"initialize\", {\"promptSuggestions\": True})\n\n\n# -p turns prompt suggestions, file checkpoints (rewind_files) and the task tools off unless the env vars force them; the user's own values win.\ndef cli_env(environ):\n    env = dict(environ)\n    env.setdefault(\"CLAUDE_CODE_ENABLE_PROMPT_SUGGESTION\", \"true\")\n    env.setdefault(\"CLAUDE_CODE_ENABLE_SDK_FILE_CHECKPOINTING\", \"1\")\n    env.setdefault(\"CLAUDE_CODE_ENABLE_TODO_TOOLS\", \"1\")\n    return env\n\n\ndef control_response(request_id, response):\n    return {\"type\": \"control_response\", \"response\": {\"subtype\": \"success\", \"request_id\": request_id, \"response\": response}}\n\n\ndef user_message(text, images=None, uuid=None):\n    content = [{\"type\": \"text\", \"text\": text}] if text else []\n    for img in images or []:\n        content.append({\"type\": \"image\", \"source\": {\"type\": \"base64\", \"media_type\": img.get(\"media_type\") or \"image/png\", \"data\": img[\"data\"]}})\n    msg = {\"type\": \"user\", \"message\": {\"role\": \"user\", \"content\": content}, \"parent_tool_use_id\": None}\n    if uuid:\n        msg[\"uuid\"] = uuid\n    return msg\n\n\ndef respond_payload(cmd):\n    out = {\"behavior\": cmd.get(\"behavior\") or \"deny\"}\n    if cmd.get(\"updatedInput\") is not None:\n        out[\"updatedInput\"] = cmd[\"updatedInput\"]\n    if cmd.get(\"updatedPermissions\"):\n        out[\"updatedPermissions\"] = cmd[\"updatedPermissions\"]\n    if cmd.get(\"message\"):\n        out[\"message\"] = cmd[\"message\"]\n    return out\n\n\ndef parse_line(line):\n    if isinstance(line, bytes):\n        line = line.decode(\"utf-8\", \"replace\")\n    line = line.strip()\n    if not line:\n        return None\n    try:\n        ev = json.loads(line)\n    except ValueError:\n        return {\"type\": \"daemon\", \"subtype\": \"raw\", \"line\": line[:2000]}\n    return ev if isinstance(ev, dict) else {\"type\": \"daemon\", \"subtype\": \"raw\", \"line\": line[:2000]}\n\n\ndef text_of(message):\n    parts = []\n    for b in (message or {}).get(\"content\") or []:\n        if isinstance(b, dict) and b.get(\"type\") == \"text\":\n            parts.append(b.get(\"text\") or \"\")\n        elif isinstance(b, str):\n            parts.append(b)\n    return \"\\n\".join(parts)\n\n\ndef apply_event(state, ev, now=0):\n    # pure: returns the state fields changed by a CLI stdout message\n    t, st = ev.get(\"type\"), ev.get(\"subtype\")\n    up = {}\n    if t == \"control_request\":\n        up[\"pending\"] = list(state.get(\"pending\") or []) + [{\"requestId\": ev.get(\"request_id\"), \"request\": ev.get(\"request\") or {}, \"ts\": now}]\n    elif t == \"control_cancel_request\":\n        up[\"pending\"] = [p for p in state.get(\"pending\") or [] if p[\"requestId\"] != ev.get(\"request_id\")]\n    elif t == \"control_response\":\n        r = ev.get(\"response\") or {}\n        if r.get(\"request_id\") == INIT_REQUEST_ID and r.get(\"subtype\") == \"success\":\n            body = r.get(\"response\") or {}\n            up[\"commands\"] = body.get(\"commands\") or []\n            up[\"models\"] = body.get(\"models\") or []\n            if body.get(\"capabilities\"):\n                up[\"capabilities\"] = body[\"capabilities\"]\n            if body.get(\"current_permission_mode\"):\n                up[\"permissionMode\"] = body[\"current_permission_mode\"]\n    elif t == \"system\":\n        if st == \"init\":\n            # a turn the CLI starts by itself (a background task's notification): the main agent is busy until its result\n            if not state.get(\"promptQueue\") and not state.get(\"followUp\"):\n                up[\"followUp\"] = True\n                up[\"turn\"] = {\"startedAt\": now, \"promptId\": None}\n            for src, dst in ((\"model\", \"model\"), (\"permissionMode\", \"permissionMode\"), (\"capabilities\", \"capabilities\"), (\"claude_code_version\", \"cliVersion\"), (\"session_id\", \"cliSessionId\")):\n                if ev.get(src) is not None:\n                    up[dst] = ev[src]\n        elif st == \"status\":\n            if ev.get(\"permissionMode\"):\n                up[\"permissionMode\"] = ev[\"permissionMode\"]\n            if \"status\" in ev:\n                up[\"activity\"] = ev[\"status\"]\n        elif st == \"session_title_changed\" and ev.get(\"title\"):\n            up[\"title\"] = ev[\"title\"]\n        elif st in (\"task_started\", \"task_updated\", \"task_notification\") and ev.get(\"task_id\"):\n            if st == \"task_started\":\n                status = \"running\"\n            elif st == \"task_updated\":\n                status = (ev.get(\"patch\") or {}).get(\"status\")\n            else:\n                status = ev.get(\"status\") or \"completed\"\n            if status:\n                up[\"tasks\"] = dict(state.get(\"tasks\") or {}, **{ev[\"task_id\"]: status})\n    elif t == \"assistant\":\n        msg = ev.get(\"message\") or {}\n        if msg.get(\"model\") and msg[\"model\"] != \"<synthetic>\":\n            up[\"model\"] = msg[\"model\"]\n        if ev.get(\"local_command_source\") or msg.get(\"model\") == \"<synthetic>\":\n            m = EFFORT_RE.search(text_of(msg))\n            if m:\n                up[\"effort\"] = m.group(1)\n    elif t == \"result\":\n        if ev.get(\"total_cost_usd\") is not None:\n            up[\"cost\"] = ev[\"total_cost_usd\"]\n        if ev.get(\"usage\") is not None:\n            up[\"usage\"] = ev[\"usage\"]\n        if ev.get(\"session_id\"):\n            up[\"cliSessionId\"] = ev[\"session_id\"]\n        queue = list(state.get(\"promptQueue\") or [])\n        if state.get(\"followUp\"):\n            up[\"followUp\"] = False\n        elif queue:\n            queue.pop(0)\n        # prompts sent mid-turn are folded into the running turn, which ends with a single result\n        uuids = state.get(\"promptUuids\") or {}\n        started = state.get(\"startedUuids\") or []\n        queue = [c for c in queue if uuids.get(c) not in started]\n        up[\"promptQueue\"] = queue\n        up[\"promptUuids\"] = {c: uuids[c] for c in queue if c in uuids}\n        up[\"startedUuids\"] = []\n        up[\"turn\"] = {\"startedAt\": now, \"promptId\": queue[0]} if queue else {\"startedAt\": None, \"promptId\": None}\n        up[\"activity\"] = None\n    elif t == \"command_lifecycle\":\n        if ev.get(\"state\") == \"started\" and ev.get(\"command_uuid\"):\n            up[\"startedUuids\"] = list(state.get(\"startedUuids\") or []) + [ev[\"command_uuid\"]]\n    elif t == \"conversation_reset\":\n        if ev.get(\"new_conversation_id\"):\n            up[\"cliSessionId\"] = ev[\"new_conversation_id\"]\n    elif t == \"rate_limit_event\":\n        up[\"rateLimit\"] = ev.get(\"rate_limit_info\")\n    return up\n\n\ndef apply_control_result(state, request, response):\n    # state fields changed by the CLI's reply to a control we sent\n    up = {}\n    sub = (request or {}).get(\"subtype\")\n    ok = (response or {}).get(\"subtype\") == \"success\"\n    body = (response or {}).get(\"response\") or {}\n    if not ok:\n        return up\n    if sub == \"get_context_usage\":\n        up[\"contextUsage\"] = body\n    elif sub == \"set_permission_mode\":\n        up[\"permissionMode\"] = body.get(\"mode\") or request.get(\"mode\")\n    elif sub == \"set_model\" and request.get(\"model\"):\n        up[\"model\"] = request[\"model\"]\n    elif sub == \"list_models\" and body.get(\"models\"):\n        up[\"models\"] = body[\"models\"]\n    elif sub == \"rename_session\" and request.get(\"title\"):\n        up[\"title\"] = request[\"title\"]\n    return up\n\n\n# target user message uuid of a successful rewind_conversation, else None\ndef rewound_target(request, response):\n    body = (response or {}).get(\"response\") or {}\n    if (request or {}).get(\"subtype\") != \"rewind_conversation\" or (response or {}).get(\"subtype\") != \"success\" or body.get(\"rewound\") is not True:\n        return None\n    return body.get(\"targetMessageUuid\") or request.get(\"target_message_uuid\")\n\n\ndef apply_prompt(state, inbox_id, text, now=0, uuid=None):\n    up = {\"promptQueue\": list(state.get(\"promptQueue\") or []) + [inbox_id]}\n    if uuid:\n        up[\"promptUuids\"] = dict(state.get(\"promptUuids\") or {}, **{inbox_id: uuid})\n    if not state.get(\"promptQueue\"):\n        up[\"turn\"] = {\"startedAt\": now, \"promptId\": inbox_id}\n    m = MODEL_CMD_RE.match(text or \"\")\n    if m:\n        up[\"model\"] = m.group(1)\n    m = EFFORT_CMD_RE.match(text or \"\")\n    if m:\n        up[\"effort\"] = m.group(1)\n    m = RENAME_CMD_RE.match(text or \"\")\n    if m:\n        up[\"title\"] = m.group(1)\n    return up\n\n\n# tasks of an ended CLI process cannot finish any more\ndef stopped_tasks(state):\n    return {k: \"stopped\" if v == \"running\" else v for k, v in (state.get(\"tasks\") or {}).items()}\n\n\ndef status_of(state):\n    if state.get(\"status\") in (\"stopped\", \"starting\", \"stopping\"):\n        return state[\"status\"]\n    if state.get(\"pending\"):\n        return \"waiting\"\n    if state.get(\"promptQueue\") or state.get(\"followUp\"):\n        return \"busy\"\n    return \"idle\"\n", "state.py": "import fcntl, json, os, re, time, uuid\n\nSEQ_RE = re.compile(rb'^\\{\"seq\": ?(\\d+)')\nEVENTS_LIMIT_BYTES = 2900 * 1024\nROTATE_BYTES = 50 * 1024 * 1024\n\n\ndef now_ms():\n    return int(time.time() * 1000)\n\n\ndef read_json(path, default=None):\n    try:\n        with open(path) as fh:\n            return json.load(fh)\n    except (OSError, ValueError):\n        return default\n\n\ndef write_atomic(path, obj):\n    tmp = path + \".tmp\"\n    with open(tmp, \"w\") as fh:\n        json.dump(obj, fh, ensure_ascii=False)\n    os.replace(tmp, path)\n\n\ndef new_state(sid, cwd):\n    return {\"version\": 0, \"sessionId\": sid, \"cliSessionId\": sid, \"cwd\": cwd, \"pid\": None, \"cliPid\": None, \"cliVersion\": None,\n            \"status\": \"stopped\", \"activity\": None, \"pending\": [], \"model\": None, \"effort\": None, \"permissionMode\": None,\n            \"capabilities\": [], \"commands\": [], \"models\": [], \"contextUsage\": None, \"rateLimit\": None, \"cost\": None,\n            \"usage\": None, \"lastSeq\": 0, \"inboxOffset\": 0, \"turn\": {\"startedAt\": None, \"promptId\": None}, \"promptQueue\": [],\n            \"stoppedAt\": None, \"reason\": None, \"startedAt\": None, \"updatedAt\": None, \"title\": None}\n\n\ndef read_state(d):\n    return read_json(os.path.join(d, \"state.json\"))\n\n\ndef write_state(d, state):\n    state[\"version\"] = int(state.get(\"version\") or 0) + 1\n    state[\"updatedAt\"] = now_ms()\n    write_atomic(os.path.join(d, \"state.json\"), state)\n\n\ndef append_line(path, obj):\n    # one write() of a full line under a lock: readers never see a torn line\n    data = (json.dumps(obj, ensure_ascii=False) + \"\\n\").encode()\n    with open(path + \".lock\", \"w\") as lock:\n        fcntl.flock(lock, fcntl.LOCK_EX)\n        with open(path, \"ab\") as fh:\n            fh.write(data)\n            fh.flush()\n\n\ndef append_inbox(d, cmd):\n    rid = str(uuid.uuid4())\n    append_line(os.path.join(d, \"inbox.jsonl\"), {\"id\": rid, \"ts\": now_ms(), \"cmd\": cmd})\n    return rid\n\n\ndef append_event(d, seq, ev):\n    append_line(os.path.join(d, \"events.jsonl\"), {\"seq\": seq, \"ts\": now_ms(), \"ev\": ev})\n\n\n# After a rotation the live file starts empty; the seq continues from events.1.jsonl.\ndef last_seq(d):\n    seq = file_last_seq(os.path.join(d, \"events.jsonl\"))\n    return seq if seq else file_last_seq(os.path.join(d, \"events.1.jsonl\"))\n\n\ndef file_last_seq(path):\n    try:\n        with open(path, \"rb\") as fh:\n            fh.seek(0, 2)\n            size = fh.tell()\n            back = 65536\n            while True:\n                fh.seek(max(0, size - back))\n                chunk = fh.read()\n                end = chunk.rfind(b\"\\n\")\n                if end < 0:\n                    return 0\n                start = chunk.rfind(b\"\\n\", 0, end) + 1\n                # a single line (compact summary, hook output) can exceed the window: widen until it fits\n                if start > 0 or back >= size:\n                    break\n                back *= 4\n    except OSError:\n        return 0\n    m = SEQ_RE.match(chunk[start:end])\n    return int(m.group(1)) if m else 0\n\n\ndef line_seq_at(fh, pos, size):\n    # seq of the first full line starting at or after pos; (None, size) past the end\n    fh.seek(pos)\n    if pos > 0:\n        fh.readline()\n    start = fh.tell()\n    if start >= size:\n        return None, size\n    m = SEQ_RE.match(fh.readline())\n    return (int(m.group(1)) if m else None), start\n\n\ndef find_offset(fh, after, size):\n    # events are appended with increasing seq, so the byte offset is searched by bisection over line starts\n    lo, hi = 0, size\n    while hi - lo > 4096:\n        mid = (lo + hi) // 2\n        seq, start = line_seq_at(fh, mid, size)\n        if start >= hi:\n            break\n        if seq is None or seq > after:\n            hi = start\n        else:\n            lo = start\n    fh.seek(lo)\n    while fh.tell() < hi:\n        start = fh.tell()\n        m = SEQ_RE.match(fh.readline())\n        if m and int(m.group(1)) > after:\n            return start\n    return hi\n\n\ndef read_events(d, after, limit=500, max_bytes=EVENTS_LIMIT_BYTES):\n    path = os.path.join(d, \"events.jsonl\")\n    out, total, more = [], 0, False\n    try:\n        with open(path, \"rb\") as fh:\n            fh.seek(0, 2)\n            size = fh.tell()\n            fh.seek(find_offset(fh, after, size) if after > 0 else 0)\n            for line in fh:\n                if not line.endswith(b\"\\n\"):\n                    break\n                m = SEQ_RE.match(line)\n                if not m or int(m.group(1)) <= after:\n                    continue\n                if len(out) >= limit or total + len(line) > max_bytes:\n                    more = True\n                    break\n                try:\n                    out.append(json.loads(line))\n                except ValueError:\n                    continue\n                total += len(line)\n    except OSError:\n        pass\n    return out, more\n\n\ndef rotate_events(d, limit=ROTATE_BYTES):\n    path = os.path.join(d, \"events.jsonl\")\n    try:\n        if os.path.getsize(path) <= limit:\n            return False\n    except OSError:\n        return False\n    with open(path + \".lock\", \"w\") as lock:\n        fcntl.flock(lock, fcntl.LOCK_EX)\n        os.replace(path, os.path.join(d, \"events.1.jsonl\"))\n    return True\n\n\n# Keeps only the bytes past `offset` (commands the daemon never consumed); returns the kept size.\ndef prune_inbox(d, offset):\n    path = os.path.join(d, \"inbox.jsonl\")\n    with open(path + \".lock\", \"w\") as lock:\n        fcntl.flock(lock, fcntl.LOCK_EX)\n        try:\n            with open(path, \"rb\") as fh:\n                fh.seek(max(0, int(offset or 0)))\n                tail = fh.read()\n        except OSError:\n            return 0\n        with open(path, \"wb\") as fh:\n            fh.write(tail)\n    return len(tail)\n\n\ndef read_new_lines(path, offset):\n    try:\n        with open(path, \"rb\") as fh:\n            fh.seek(0, 2)\n            size = fh.tell()\n            if size <= offset:\n                return [], offset\n            fh.seek(offset)\n            data = fh.read(size - offset)\n    except OSError:\n        return [], offset\n    end = data.rfind(b\"\\n\")\n    if end < 0:\n        return [], offset\n    lines = data[:end].split(b\"\\n\")\n    return lines, offset + end + 1\n", "tui.py": "\"\"\"Interactive Claude TUIs: ~/.claude/sessions/<pid>.json (written by the CLI), SIGTERM, transcript paths.\"\"\"\nimport glob, json, os, re, signal, time\n\nHOME = os.path.expanduser(\"~\")\nCLAUDE = os.path.join(HOME, \".claude\")\nSESSIONS = os.path.join(CLAUDE, \"sessions\")\n\n\ndef alive(pid):\n    try:\n        os.kill(int(pid), 0)\n        return True\n    except PermissionError:\n        return True\n    except Exception:\n        return False\n\n\ndef transcript_path(cwd, sid):\n    return os.path.join(CLAUDE, \"projects\", re.sub(r\"[^A-Za-z0-9]\", \"-\", cwd or \"\"), str(sid) + \".jsonl\")\n\n\ndef live_sessions():\n    out = []\n    for f in glob.glob(os.path.join(SESSIONS, \"*.json\")):\n        try:\n            with open(f) as fh:\n                s = json.load(fh)\n        except Exception:\n            continue\n        pid = s.get(\"pid\")\n        if not isinstance(pid, int) or s.get(\"kind\", \"interactive\") != \"interactive\" or not alive(pid):\n            continue\n        out.append({\"pid\": pid, \"sessionId\": s.get(\"sessionId\"), \"cwd\": s.get(\"cwd\"), \"status\": s.get(\"status\"),\n                    \"waitingFor\": s.get(\"waitingFor\"), \"updatedAt\": s.get(\"updatedAt\") or 0, \"startedAt\": s.get(\"startedAt\")})\n    out.sort(key=lambda s: -s[\"updatedAt\"])\n    return out\n\n\n# pid wins (it survives /clear, which changes sessionId), then the session id, then the newest TUI in cwd.\ndef find(req):\n    live = live_sessions()\n    pid, sid, cwd = req.get(\"pid\"), req.get(\"cliSessionId\"), req.get(\"cwd\")\n    if pid:\n        found = next((s for s in live if s[\"pid\"] == int(pid)), None)\n        if found is not None:\n            return found\n    if sid:\n        found = next((s for s in live if s[\"sessionId\"] == sid), None)\n        if found is not None:\n            return found\n    if cwd and not sid and not pid:\n        return next((s for s in live if s[\"cwd\"] == cwd), None)\n    return None\n\n\ndef op_find(req):\n    return find(req)\n\n\ndef op_exit(req):\n    s = find(req)\n    if s is None:\n        return {\"exited\": True, \"found\": False, \"sessionId\": req.get(\"cliSessionId\")}\n    pid = s[\"pid\"]\n    try:\n        os.kill(pid, signal.SIGTERM)\n    except OSError:\n        return {\"exited\": not alive(pid), \"found\": True, \"sessionId\": s[\"sessionId\"]}\n    deadline = time.time() + float(req.get(\"waitS\") or 8)\n    while time.time() < deadline and alive(pid):\n        time.sleep(0.1)\n    if alive(pid):\n        try:\n            os.kill(pid, signal.SIGKILL)\n        except OSError:\n            pass\n        time.sleep(0.2)\n    return {\"exited\": not alive(pid), \"found\": True, \"sessionId\": s[\"sessionId\"]}\n\n\ndef op_transcript_path(req):\n    path = transcript_path(req.get(\"cwd\") or \"\", req.get(\"cliSessionId\") or \"\")\n    return {\"path\": path, \"exists\": os.path.isfile(path)}\n\n\nOPS = {\"tuiFind\": op_find, \"tuiExit\": op_exit, \"transcriptPath\": op_transcript_path}\n"}  # generated by build.py
STATUSLINE_SRC = "import json, os, re, subprocess, sys, time\n\nHOME = os.path.expanduser(\"~\")\nSTATE = os.path.join(os.environ.get(\"XDG_CACHE_HOME\") or os.path.join(HOME, \".cache\"), \"claude-chat\")\nCONFIG = os.path.join(os.environ.get(\"XDG_CONFIG_HOME\") or os.path.join(HOME, \".config\"), \"claude-chat\", \"config.json\")\nSAMPLE_EVERY = 180\nKEEP = 2 * 86400\n\n\ndef write_atomic(path, text):\n    os.makedirs(os.path.dirname(path), exist_ok=True)\n    tmp = \"%s.%d.tmp\" % (path, os.getpid())\n    with open(tmp, \"w\") as fh:\n        fh.write(text)\n    os.replace(tmp, path)\n\n\ndef save_status(payload, now):\n    sid = str(payload.get(\"session_id\") or \"\")\n    if re.fullmatch(r\"[0-9A-Za-z_-]+\", sid):\n        write_atomic(os.path.join(STATE, \"statusline\", sid + \".json\"), json.dumps({\"payload\": payload, \"updatedAt\": now}))\n\n\ndef save_sample(payload, now):\n    import fcntl\n    rl = payload.get(\"rate_limits\") or {}\n    five = (rl.get(\"five_hour\") or {}).get(\"used_percentage\")\n    seven = (rl.get(\"seven_day\") or {}).get(\"used_percentage\")\n    if five is None and seven is None:\n        return\n    path = os.path.join(STATE, \"usage-history.jsonl\")\n    os.makedirs(STATE, exist_ok=True)\n    with open(path + \".lock\", \"w\") as lock:\n        fcntl.flock(lock, fcntl.LOCK_EX)\n        try:\n            with open(path) as fh:\n                lines = fh.read().splitlines()\n        except OSError:\n            lines = []\n        rows = []\n        for line in lines:\n            try:\n                rows.append(json.loads(line))\n            except ValueError:\n                pass\n        if rows and now - rows[-1].get(\"ts\", 0) < SAMPLE_EVERY:\n            return\n        sample = json.dumps({\"ts\": int(now), \"five\": five, \"seven\": seven})\n        kept = [r for r in rows if r.get(\"ts\", 0) >= now - KEEP]\n        if len(kept) == len(lines):\n            with open(path, \"a\") as fh:\n                fh.write(sample + \"\\n\")\n        else:\n            write_atomic(path, \"\".join(json.dumps(r) + \"\\n\" for r in kept) + sample + \"\\n\")\n\n\ndef default_line(payload):\n    model = (payload.get(\"model\") or {}).get(\"display_name\") or \"Claude\"\n    pct = (payload.get(\"context_window\") or {}).get(\"used_percentage\")\n    return model if pct is None else \"%s \u00b7 ctx %d%%\" % (model, pct)\n\n\ndef main():\n    raw = sys.stdin.buffer.read()\n    now = time.time()\n    try:\n        payload = json.loads(raw.decode(\"utf-8\", \"replace\"))\n    except ValueError:\n        payload = None\n    payload = payload if isinstance(payload, dict) else {}\n    for save in (save_status, save_sample):\n        try:\n            save(payload, now)\n        except Exception:\n            pass\n    try:\n        with open(CONFIG) as fh:\n            chain = json.load(fh).get(\"statuslineChain\")\n    except Exception:\n        chain = None\n    if chain:\n        try:\n            r = subprocess.run(chain, shell=True, input=raw, stdout=subprocess.PIPE, timeout=5)\n            sys.stdout.buffer.write(r.stdout)\n            return\n        except Exception:\n            pass\n    try:\n        line = default_line(payload)\n    except Exception:\n        line = \"Claude\"\n    sys.stdout.buffer.write((line + \"\\n\").encode(\"utf-8\"))\n\n\nmain()\n"  # generated by build.py


def fail(msg):
    raise SystemExit("claude-chat setup: " + msg)


def read_json(path, default):
    try:
        with open(path) as fh:
            return json.load(fh)
    except FileNotFoundError:
        return default
    except ValueError as e:
        fail("%s is not valid JSON (%s)" % (path, e))


def write_json(path, data):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    tmp = path + ".claude-chat-tmp"
    with open(tmp, "w") as fh:
        json.dump(data, fh, indent=2, ensure_ascii=False)
        fh.write("\n")
    os.replace(tmp, path)


def is_ours(command):
    return "claude-chat/statusline.py" in (command or "")


def which(name, *extra):
    for c in [shutil.which(name)] + [os.path.join(HOME, x) for x in extra]:
        if c and os.access(c, os.X_OK):
            return c
    return None


def install_statusline(config, done):
    os.makedirs(SHARE, exist_ok=True)
    target = os.path.join(SHARE, "statusline.py")
    with open(target, "w") as fh:
        fh.write(STATUSLINE_SRC)
    os.chmod(target, 0o755)
    done.append("installed " + target)
    settings = read_json(SETTINGS, {})
    if not isinstance(settings, dict):
        fail(SETTINGS + " is not a JSON object")
    prev = settings.get("statusLine") if isinstance(settings.get("statusLine"), dict) else {}
    if is_ours(prev.get("command")):
        done.append("statusLine already set")
        return
    if prev.get("command"):
        config["statuslineChain"] = prev["command"]
        done.append("chained previous statusLine: " + prev["command"])
    bak = SETTINGS + ".claude-chat-bak"
    if os.path.exists(SETTINGS) and not os.path.exists(bak):
        shutil.copy2(SETTINGS, bak)
        done.append("backup " + bak)
    line = dict(prev)
    line.update({"type": "command", "command": OUR_COMMAND})
    settings["statusLine"] = line
    write_json(SETTINGS, settings)
    done.append("statusLine -> " + OUR_COMMAND)


def install_server(done):
    if not SERVER_SRC:
        fail("server sources not embedded (run server/build.py)")
    target = os.path.join(SHARE, "claude_chat")
    os.makedirs(target, exist_ok=True)
    for name, src in SERVER_SRC.items():
        with open(os.path.join(target, name), "w") as fh:
            fh.write(src)
    for name in os.listdir(target):
        if name.endswith(".py") and name not in SERVER_SRC:
            os.unlink(os.path.join(target, name))
    done.append("installed " + target + " (%d files)" % len(SERVER_SRC))


def cli_list():
    cli = os.path.join(SHARE, "claude_chat", "cli.py")
    if not os.path.isfile(cli):
        return None
    try:
        r = subprocess.run([sys.executable, cli], input='{"op": "list"}', capture_output=True, text=True, timeout=20)
        out = json.loads(r.stdout or "{}")
    except (OSError, ValueError, subprocess.TimeoutExpired) as e:
        return {"error": str(e)}
    if "error" in out:
        return {"error": out["error"]}
    return [{k: s.get(k) for k in ("sessionId", "status", "pid", "cwd", "reason")} for s in out.get("sessions") or []]


def stop_daemons(done):
    cli = os.path.join(SHARE, "claude_chat", "cli.py")
    daemons = cli_list()
    for s in daemons if isinstance(daemons, list) else []:
        if s.get("status") == "stopped":
            continue
        try:
            subprocess.run([sys.executable, cli], input=json.dumps({"op": "stop", "sessionId": s["sessionId"], "force": True}), capture_output=True, text=True, timeout=20)
            done.append("stopped daemon " + s["sessionId"])
        except (OSError, subprocess.TimeoutExpired) as e:
            done.append("could not stop daemon %s: %s" % (s["sessionId"], e))


def uninstall(done):
    config = read_json(CONFIG, {})
    settings = read_json(SETTINGS, None)
    stop_daemons(done)
    line = settings.get("statusLine") if isinstance(settings, dict) else None
    if isinstance(line, dict) and is_ours(line.get("command")):
        chain = config.get("statuslineChain")
        if chain:
            line["command"] = chain
            done.append("statusLine restored: " + chain)
        else:
            del settings["statusLine"]
            done.append("statusLine removed")
        write_json(SETTINGS, settings)
    if os.path.isdir(SHARE):
        shutil.rmtree(SHARE)
        done.append("removed " + SHARE)
    if os.path.exists(CONFIG):
        os.unlink(CONFIG)
        done.append("removed " + CONFIG)
        if not os.listdir(os.path.dirname(CONFIG)):
            os.rmdir(os.path.dirname(CONFIG))
    done.append("kept state in " + STATE)


def check():
    settings = read_json(SETTINGS, {})
    line = settings.get("statusLine") if isinstance(settings, dict) else None
    command = line.get("command") if isinstance(line, dict) else None
    config = read_json(CONFIG, None)
    claude_bin = (config or {}).get("claudeBin") if isinstance(config, dict) else None
    pkg = os.path.join(SHARE, "claude_chat")
    installed = os.path.isfile(os.path.join(pkg, "cli.py"))
    print(json.dumps({
        "python": sys.version.split()[0],
        "platform": sys.platform,
        "muxy": which("muxy", ".local/bin/muxy"),
        "claude": claude_bin if claude_bin and os.access(claude_bin, os.X_OK) else which("claude", ".local/bin/claude", ".claude/local/claude"),
        "claudeBin": claude_bin,
        "server": {
            "installed": installed,
            "dir": pkg,
            "files": sorted(n for n in os.listdir(pkg) if n.endswith(".py")) if installed else [],
            "current": all(os.path.isfile(os.path.join(pkg, n)) and open(os.path.join(pkg, n)).read() == src for n, src in SERVER_SRC.items()) if installed else False,
        },
        "daemons": cli_list(),
        "statusline": {
            "state": "ours" if is_ours(command) else ("other" if command else "none"),
            "command": command,
            "installed": os.path.isfile(os.path.join(SHARE, "statusline.py")),
        },
        "config": config,
        "configPath": CONFIG,
        "stateDir": STATE,
    }, indent=2))


def main():
    ap = argparse.ArgumentParser(prog="setup.py", description="claude-chat server setup")
    ap.add_argument("--server", action="store_true", help="install the agent host (claude_chat package) under ~/.local/share/claude-chat")
    ap.add_argument("--statusline", action="store_true", help="install the statusline wrapper (usage strip)")
    ap.add_argument("--open-bridge-dir", help="server dir shared with the host for open-file requests")
    ap.add_argument("--open-bridge-root", help="server path the host can map to its own folder")
    ap.add_argument("--uninstall", action="store_true", help="stop the daemons, remove the package, the statusline wrapper and the config")
    ap.add_argument("--check", action="store_true", help="print a JSON diagnosis: python, claude, package state, running daemons")
    a = ap.parse_args(sys.argv[1:])
    bridge = a.open_bridge_dir or a.open_bridge_root
    if a.check or a.uninstall:
        if a.server or a.statusline or bridge or (a.check and a.uninstall):
            fail("--check and --uninstall cannot be combined with other options")
        if a.check:
            check()
            return
        done = []
        uninstall(done)
        print("\n".join(done))
        return
    if not (a.server or a.statusline or bridge):
        fail("nothing to do (use --server, --statusline, --open-bridge-dir/--open-bridge-root, --uninstall or --check)")
    if bool(a.open_bridge_dir) != bool(a.open_bridge_root):
        fail("--open-bridge-dir and --open-bridge-root must be given together")
    config = read_json(CONFIG, {})
    if not isinstance(config, dict):
        fail(CONFIG + " is not a JSON object")
    done = []
    if a.server:
        install_server(done)
    if a.statusline:
        install_statusline(config, done)
    if bridge:
        d = os.path.abspath(os.path.expanduser(a.open_bridge_dir))
        root = os.path.abspath(os.path.expanduser(a.open_bridge_root))
        if not os.path.isdir(root):
            fail("open-bridge root does not exist: " + root)
        for sub in ("req", "res"):
            os.makedirs(os.path.join(d, sub), exist_ok=True)
        config["openBridge"] = {"dir": d, "root": root}
        done.append("openBridge: dir=%s root=%s" % (d, root))
    write_json(CONFIG, config)
    done.append("config " + CONFIG)
    print("\n".join(done))


try:
    main()
except OSError as e:
    fail(str(e))
